Value.Calculation:
Let ( [
		~iso = GetValue ( Substitute ( $effectiveDate ; "T" ; Char ( 13 ) ) ; 1 )
	];

	If ( Length ( ~iso ) < 10 ;
		Get ( CurrentDate ) ;
		Date (
			GetAsNumber ( Middle ( ~iso ; 6 ; 2 ) ) ;
			GetAsNumber ( Right ( ~iso ; 2 ) ) ;
			GetAsNumber ( Left ( ~iso ; 4 ) )
		)
	)
)

JSONSetElement ( $cons ; $batchId ;
	GetAsNumber ( JSONGetElement ( $cons ; $batchId ) ) + $sign * GetAsNumber ( epSQLResult ( $i ; 2 ; "rs_con" ) ) ;
	JSONNumber
)

JSONSetElement ( $rows ; "[" & $out & "]" ;
	JSONSetElement ( "{}" ;
		[ "batchId" ; $batchId ; JSONString ] ;
		[ "artikalId" ; epSQLResult ( $i ; 8 ; "rs_evt" ) ; JSONString ] ;
		[ "sifra" ; epSQLResult ( $i ; 9 ; "rs_evt" ) ; JSONString ] ;
		[ "naziv" ; epSQLResult ( $i ; 10 ; "rs_evt" ) ; JSONString ] ;
		[ "jm" ; epSQLResult ( $i ; 7 ; "rs_evt" ) ; JSONString ] ;
		[ "kolicina" ; $qty ; JSONNumber ] ;
		[ "staraMPCijena" ; $cijena ; JSONNumber ] ;
		[ "staraMPCijenaBezPDV" ; $neto ; JSONNumber ] ;
		[ "stariPDVPostotak" ; $pdv ; JSONNumber ] ;
		[ "nabavnaCijenaEfektivna" ; $nabavna ; JSONNumber ] ;
		[ "stariRUCIznos" ; Round ( $neto - $nabavna ; 4 ) ; JSONNumber ] ;
		[ "kalkulacijaId" ; epSQLResult ( $i ; 4 ; "rs_evt" ) ; JSONString ] ;
		[ "kalkulacijaBroj" ; epSQLResult ( $i ; 5 ; "rs_evt" ) ; JSONString ]
	) ;
	JSONObject
)

Response_SetData ( JSONSetElement ( "{}" ;
	[ "rows" ; $rows ; JSONArray ] ;
	[ "count" ; $out ; JSONNumber ] ;
	[ "effectiveDate" ; Year ( $effDate ) & "-" & Right ( "0" & Month ( $effDate ) ; 2 ) & "-" & Right ( "0" & Day ( $effDate ) ; 2 ) ; JSONString ]
) )
